function entry(partial: Partial<SearchEntry> & Pick<SearchEntry, "title" | "url">): SearchEntry {
  return {
    chapter: partial.chapter ?? partial.title,
    navTitle: partial.navTitle ?? "",
    text: partial.text ?? "",
    symbols: partial.symbols ?? [],
    ...partial,
  }
}

