})

test("compareVersions orders x.y.z numerically and rejects other versions", () => {
  const versions = ["0.10.0", "0.2.10", "0.2.9", "1.0.0", "0.2.9"]
  expect(versions.sort(compareVersions)).toEqual(["0.2.9", "0.2.9", "0.2.10", "0.10.0", "1.0.0"])
  expect(() => compareVersions("0.0.0-20261004-7dad729e", "0.1.0")).toThrow()
  expect(isApiVersion("0.5.17")).toBe(true)
  expect(isApiVersion("0.5.17-dry")).toBe(false)
})

test("diffFeatures returns sorted additions and removals", () => {
  expect(diffFeatures([`${M}: const b: 1`, `${M}: const a: 1`], [`${M}: const c: 1`, `${M}: const a: 1`])).toEqual({
    added: [`${M}: const c: 1`],
    removed: [`${M}: const b: 1`],
  })
})

describe("API files", () => {
  const text = [
    "base 0.5.16",
    // Keys ignore modifiers, so `static method CliRenderer.create` sorts as `method CliRenderer.create`.
    `+ ${M}: static method CliRenderer.create(): CliRenderer`,
    `- ${M}: method CliRenderer.dumpBuffers(timestamp?: number): void`,
    `- ${M}: method CliRenderer.suspend(): void`,
    `+ ${M}: method CliRenderer.suspend(): Promise<void>`,
    "",
  ].join("\n")

  test("parse and format round trip", () => {
    const release = parseApiFile("0.5.17", text)
    expect(release).toEqual({
      version: "0.5.17",
      base: "0.5.16",
      added: [
        `${M}: static method CliRenderer.create(): CliRenderer`,
        `${M}: method CliRenderer.suspend(): Promise<void>`,
      ],
      removed: [
        `${M}: method CliRenderer.dumpBuffers(timestamp?: number): void`,
        `${M}: method CliRenderer.suspend(): void`,
      ],
    })
    expect(formatApiFile(release)).toBe(text)
    expect(
      formatApiFile({ ...release, added: [...release.added].reverse(), removed: [...release.removed].reverse() }),
    ).toBe(text)
  })

  test("a file without changes holds only the header", () => {
    expect(formatApiFile({ version: "0.1.0", base: null, added: [], removed: [] })).toBe("base none\n")
    expect(parseApiFile("0.1.0", "base none\n")).toEqual({ version: "0.1.0", base: null, added: [], removed: [] })
  })

  test.each([
    ["", "first line"],
    ["base latest\n", "first line"],
    [`base none\n${M}: const a: 1\n`, "expected"],
    [`base none\n+ ${M}: bogus a\n`, "Unknown API kind"],
  ])("rejects %j", (body, message) => expect(() => parseApiFile("0.1.0", body)).toThrow(message))
})

// A history with a maintenance release: 0.2.1 was published after 0.3.0, relative to 0.2.0.
const files = [
  { version: "0.1.0", text: `base none\n+ ${M}: const keep: 1\n+ ${M}: function f(): void\n+ ${M}: const gone: 1\n` },
  { version: "0.2.0", text: `base 0.1.0\n- ${M}: function f(): void\n+ ${M}: function f(): Promise<void>\n` },
  {
    version: "0.3.0",
    text: `base 0.2.0\n- ${M}: const gone: 1\n+ ${M}: deprecated const keep: 1\n- ${M}: const keep: 1\n`,
  },
  { version: "0.2.1", text: `base 0.2.0\n+ ${M}: const backport: 1\n` },
  { version: "0.3.1", text: `base 0.3.0\n+ ${M}: const gone: 2\n` },
].map((file) => ({ ...file, text: formatApiFile(parseApiFile(file.version, file.text)) }))

describe("ApiHistory", () => {
  const history = ApiHistory.fromFiles(files)

  test("versions ascend and snapshots replay the base chain", () => {
    expect(history.versions).toEqual(["0.1.0", "0.2.0", "0.2.1", "0.3.0", "0.3.1"])
    expect(history.latest).toBe("0.3.1")
    expect([...history.snapshot("0.2.1")].sort()).toEqual([
      `${M}: const backport: 1`,
      `${M}: const gone: 1`,
      `${M}: const keep: 1`,
      `${M}: function f(): Promise<void>`,
    ])
    expect([...history.snapshot("0.3.0")].sort()).toEqual([
      `${M}: deprecated const keep: 1`,
      `${M}: function f(): Promise<void>`,
    ])
  })

  test("changes group lines by key", () => {
    expect(
      history.changes("0.3.0").map(({ key, type, before, after }) => [key, type, before.length, after.length]),
    ).toEqual([
      [`${M}: const gone`, "removed", 1, 0],
      [`${M}: const keep`, "deprecated", 1, 1],
    ])
    expect(history.changes("0.2.0").map((change) => [change.name, change.type])).toEqual([["f", "changed"]])
    expect(history.changes("0.2.1").map((change) => [change.kind, change.name, change.type])).toEqual([
      ["const", "backport", "added"],
    ])
    expect(history.changes("0.1.0").every((change) => change.type === "added")).toBe(true)
  })

  test("keyHistory records since, changes, deprecation, removal, and re-addition", () => {
    const keys = history.keyHistory()
    expect(keys.get(`${M}: function f`)).toEqual({ key: `${M}: function f`, since: "0.1.0", changedIn: ["0.2.0"] })
    expect(keys.get(`${M}: const keep`)).toEqual({
      key: `${M}: const keep`,
      since: "0.1.0",
      changedIn: [],
      deprecatedIn: "0.3.0",
    })
    // The maintenance release is older than 0.3.0, which does not contain the backport.
    expect(keys.get(`${M}: const backport`)).toMatchObject({ since: "0.2.1", removedIn: "0.3.0" })
    expect(keys.get(`${M}: const gone`)).toEqual({ key: `${M}: const gone`, since: "0.1.0", changedIn: [] })
    const upTo = history.keyHistory("0.3.0")
    expect(upTo.get(`${M}: const gone`)).toMatchObject({ since: "0.1.0", removedIn: "0.3.0" })
    expect(history.keyHistory("0.2.0").get(`${M}: const keep`)?.deprecatedIn).toBeUndefined()
  })

  test("squash starts the history at a snapshot and keeps the API of every later release", () => {
    const squashed = ApiHistory.fromReleases(history.squash("0.3.0"))
    expect(squashed.versions).toEqual(["0.3.0", "0.3.1"])
    expect(squashed.release("0.3.0")).toEqual({
      version: "0.3.0",
      base: null,
      added: [`${M}: deprecated const keep: 1`, `${M}: function f(): Promise<void>`],
      removed: [],
    })
    expect(squashed.release("0.3.1")).toBe(history.release("0.3.1"))
    for (const version of squashed.versions) expect(squashed.snapshot(version)).toEqual(history.snapshot(version))
    expect(squashed.changes("0.3.0").every((change) => change.type === "added")).toBe(true)
    expect(squashed.keyHistory().get(`${M}: const keep`)).toEqual({
      key: `${M}: const keep`,
      since: "0.3.0",
      changedIn: [],
      deprecatedIn: "0.3.0",
    })
    // 0.3.0 is based on 0.2.0, which a history that starts at the 0.2.1 backport does not keep.
    expect(() => history.squash("0.2.1")).toThrow("0.3.0: base 0.2.0 is older than 0.2.1")
    expect(() => history.squash("0.2.5")).toThrow("No API file for 0.2.5")
  })

  test("unknown versions and broken chains throw", () => {
    expect(() => history.snapshot("9.9.9")).toThrow("No API file")
    expect(() => ApiHistory.fromFiles([{ version: "0.1.0", text: "base 0.0.9\n" }])).toThrow("No API file for 0.0.9")
    expect(() =>
      ApiHistory.fromFiles([
        { version: "0.1.0", text: "base 0.2.0\n" },
        { version: "0.2.0", text: "base 0.1.0\n" },
      ]),
    ).toThrow("cycle")
  })
})

// The reference walks every snapshot in version order. keyHistory must agree with it while it keeps only
// the states that later versions use as a base.
function referenceKeyHistory(history: ApiHistory, upTo?: string): Map<string, ApiKeyHistory> {
  const result = new Map<string, ApiKeyHistory>()
  let previous = new Map<string, string[]>()
  const deprecated = (lines: string[]) => lines.every((line) => parseFeature(line).modifiers[0] === "deprecated")
  for (const version of history.versions.filter((v) => upTo === undefined || compareVersions(v, upTo) <= 0)) {
    const next = new Map<string, string[]>()
    for (const line of history.snapshot(version)) {
      const key = featureKey(parseFeature(line))
      next.set(key, [...(next.get(key) ?? []), line])
    }
    for (const key of new Set([...previous.keys(), ...next.keys()])) {
      const before = previous.get(key) ?? []
      const after = next.get(key) ?? []
      const entry = result.get(key)
      if (after.length === 0) {
        if (before.length > 0) entry!.removedIn = version
        continue
      }
      if (entry === undefined || before.length === 0) {
        const fresh = entry ?? { key, since: version, changedIn: [] }
        fresh.removedIn = undefined
        fresh.deprecatedIn = deprecated(after) ? version : undefined
        result.set(key, fresh)
        continue
      }
      const lost = before.filter((line) => !after.includes(line))
      const gained = after.filter((line) => !before.includes(line))
      if (lost.length + gained.length === 0) continue
      if (!deprecated(before) && deprecated(after)) entry.deprecatedIn = version
      if (deprecated(before) && !deprecated(after)) entry.deprecatedIn = undefined
      const onlyDeprecated =
        lost.length > 0 &&
        lost.length === gained.length &&
        lost.every((line) => {
          const feature = parseFeature(line)
          return (
            !feature.modifiers.includes("deprecated") &&
            gained.includes(formatFeature({ ...feature, modifiers: ["deprecated", ...feature.modifiers] }))
          )
        })
      if (!onlyDeprecated) entry.changedIn.push(version)
    }
    previous = next
  }
  return result
}

function normalized(map: Map<string, ApiKeyHistory>): ApiKeyHistory[] {
  return [...map.values()]
    .map((entry) => JSON.parse(JSON.stringify(entry)) as ApiKeyHistory)
    .sort((a, b) => (a.key < b.key ? -1 : 1))
}

test("keyHistory matches a snapshot-by-snapshot reference on random histories", () => {
  let seed = 7
  const random = (limit: number) => {
    seed = (seed * 1103515245 + 12345) % 2147483648
    return seed % limit
  }
  const pool = ["a", "b", "c", "d", "e"].flatMap((name) => [
    `${M}: const ${name}: 1`,
    `${M}: const ${name}: 2`,
    `${M}: deprecated const ${name}: 1`,
    `${M}: function ${name}(): void`,
    `${M}: function ${name}(x: number): void`,
  ])
  for (let round = 0; round < 40; round++) {
    const files: Array<{ version: string; text: string }> = []
    const snapshots = new Map<string, Set<string>>()
    const count = 2 + random(10)
    for (let index = 0; index < count; index++) {
      const version = `0.${index}.0`
      // Mostly linear, with some bases further back, as a maintenance release has.
      const base = index === 0 ? null : random(4) === 0 ? `0.${random(index)}.0` : `0.${index - 1}.0`
      const next = new Set(base === null ? [] : snapshots.get(base))
      for (let change = random(6); change > 0; change--) {
        const line = pool[random(pool.length)]!
        if (next.has(line)) next.delete(line)
        else next.add(line)
      }
      snapshots.set(version, next)
      const diff = diffFeatures(base === null ? [] : snapshots.get(base)!, next)
      files.push({ version, text: formatApiFile({ version, base, ...diff }) })
    }
    // Store the files out of order: a later version can be the base of an earlier one.
    const history = ApiHistory.fromFiles(files.reverse())
    expect(checkApiFiles(files)).toEqual([])
    for (const [version, snapshot] of snapshots)
      expect([...history.snapshot(version)].sort()).toEqual([...snapshot].sort())
    expect(normalized(history.keyHistory())).toEqual(normalized(referenceKeyHistory(history)))
    const upTo = `0.${random(count)}.0`
    expect(normalized(history.keyHistory(upTo))).toEqual(normalized(referenceKeyHistory(history, upTo)))
  }
})

describe("checkApiFiles", () => {
  test("accepts a valid history", () => expect(checkApiFiles(files)).toEqual([]))

  test.each([
    [
      "an unsorted file",
      { version: "0.4.0", text: `base 0.3.1\n+ ${M}: const z: 1\n+ ${M}: const a: 1\n` },
      "canonical order",
    ],
    ["an unknown base", { version: "0.4.0", text: "base 0.3.9\n" }, "base 0.3.9 has no API file"],
    [
      "a feature listed twice",
      { version: "0.4.0", text: `base 0.3.1\n+ ${M}: const a: 1\n+ ${M}: const a: 1\n` },
      "twice",
    ],
    [
      "an addition of a present feature",
      { version: "0.4.0", text: `base 0.3.1\n+ ${M}: const gone: 2\n` },
      "adds a present",
    ],
    [
      "a removal of a missing feature",
      { version: "0.4.0", text: `base 0.3.1\n- ${M}: const gone: 1\n` },
      "removes a missing",
    ],
    ["a bad file name", { version: "next", text: "base none\n" }, "not an x.y.z version"],
  ])("reports %s", (_, file, message) => {
    const problems = checkApiFiles([...files, file])
    expect(problems).toHaveLength(1)
    expect(problems[0]).toContain(message)
  })
})

test("loadApiHistory reads the version files of a directory", async () => {
  const dir = await mkdtemp(join(tmpdir(), "api-history-"))
  try {
    for (const file of files) await writeFile(join(dir, `${file.version}.txt`), file.text)
    await writeFile(join(dir, "README.md"), "not an API file")
    const history = await loadApiHistory(dir)
    expect(history.versions).toEqual(["0.1.0", "0.2.0", "0.2.1", "0.3.0", "0.3.1"])
  } finally {
    await rm(dir, { recursive: true, force: true })
  }
})

import { describe, expect, it } from "bun:test"
import { BoxRenderable, LineNumberRenderable, TextRenderable } from "@opentui/core"
import { createTestRenderer } from "@opentui/core/testing"
import { batch, createRoot, createSignal } from "solid-js"
import { createSlotNode, insert, insertNode } from "../index.js"
import { LayoutSlotRenderable } from "../src/elements/slot.js"

type MoveOrder = "remove-then-insert" | "insert-then-remove"

async function runMoveScenario(order: MoveOrder) {
  const setup = await createTestRenderer({ width: 40, height: 10 })
  const parentA = new BoxRenderable(setup.renderer, {
    id: `slot-parent-a-${order}`,
    width: 10,
    height: 1,
  })
  const parentB = new BoxRenderable(setup.renderer, {
    id: `slot-parent-b-${order}`,
    width: 10,
    height: 1,
  })

  setup.renderer.root.add(parentA)
  setup.renderer.root.add(parentB)

  const slot = createSlotNode()
  const controls = createRoot((dispose) => {
    const [inParentA, setInParentA] = createSignal(true)
    const [inParentB, setInParentB] = createSignal(false)

    const mountInParentA = () => (inParentA() ? slot : null)
    const mountInParentB = () => (inParentB() ? slot : null)

    if (order === "remove-then-insert") {
      insert(parentA, mountInParentA)
      insert(parentB, mountInParentB)
    } else {
      insert(parentB, mountInParentB)
      insert(parentA, mountInParentA)
    }

    return {
      dispose,
      move(): void {
        batch(() => {
          setInParentB(true)
          setInParentA(false)
        })
      },
    }
  })

  const originalChild = parentA.getChildren()[0]
  if (!originalChild) {
    throw new Error(`Expected slot child in parent A for ${order}`)
  }

  controls.move()

  const movedChild = parentB.getChildren()[0]
  if (!movedChild) {
    throw new Error(`Expected slot child in parent B for ${order}`)
  }

  await Bun.sleep(0)

  return {
    controls,
    movedChild,
    originalChild,
    parentA,
    parentB,
    setup,
    slot,
  }
}

describe("slot placeholder moves", () => {
  it.each([false, true])("keeps rejected slots reusable (existing host: %p)", async (attached) => {
    const setup = await createTestRenderer({ width: 20, height: 5 })
    const rejecting = new LineNumberRenderable(setup.renderer, {})
    setup.renderer.root.add(rejecting)
    const slot = createSlotNode()

    try {
      if (attached) insertNode(setup.renderer.root, slot)
      const rejected = slot.getSlotChild(rejecting)
      if (!(rejected instanceof LayoutSlotRenderable)) throw new Error("Expected layout placeholder")
      insertNode(rejecting, slot)

      expect(rejected.isFreed()).toBe(true)
      expect(slot.getSlotChildForRemoval(rejecting)).toBeUndefined()

      insertNode(rejecting, new TextRenderable(setup.renderer, { content: "target" }), slot)
      expect(slot.getSlotChildForRemoval(rejecting)).toBeUndefined()

      insertNode(setup.renderer.root, slot)
      const accepted = slot.getSlotChild(setup.renderer.root)
      if (!(accepted instanceof LayoutSlotRenderable)) throw new Error("Expected layout placeholder")
      expect(accepted.parent).toBe(setup.renderer.root)
      expect(accepted.isFreed()).toBe(false)
      setup.renderer.destroy()
      expect(accepted.isFreed()).toBe(true)
    } finally {
      setup.renderer.destroy()
      slot.destroy()
    }
  })

  it("preserves attachment for remove-then-insert registration order", async () => {
    const { controls, movedChild, originalChild, parentA, parentB, setup, slot } =
      await runMoveScenario("remove-then-insert")

    try {
      expect(movedChild).not.toBe(originalChild)
      expect(originalChild.isDestroyed).toBe(true)
      expect(parentA.getChildren()).toHaveLength(0)
      expect(parentB.getChildren()).toHaveLength(1)
      expect(parentB.getChildren()[0]).toBe(movedChild)
      expect(movedChild.parent).toBe(parentB)
      expect(movedChild.isDestroyed).toBe(false)
      expect((slot as any).destroyed).toBe(false)
    } finally {
      controls.dispose()
      setup.renderer.destroy()
    }
  })

  it("recreates attached layout placeholders for insert-then-remove moves", async () => {
    const { controls, movedChild, originalChild, parentA, parentB, setup, slot } =
      await runMoveScenario("insert-then-remove")

    try {
      expect(movedChild).not.toBe(originalChild)
      expect(parentA.getChildren()).toHaveLength(0)
      expect(parentB.getChildren()).toHaveLength(1)
      expect(parentB.getChildren()[0]).toBe(movedChild)
      expect(movedChild.parent).toBe(parentB)
      expect(movedChild.isDestroyed).toBe(false)
      expect((slot as any).destroyed).toBe(false)
    } finally {
      controls.dispose()
      setup.renderer.destroy()
    }
  })

  it.each(["remove", "destroy subtree"])("preserves the other attached slot host on %s", async (cleanup) => {
    const setup = await createTestRenderer({ width: 40, height: 10 })
    const parentA = new BoxRenderable(setup.renderer, {
      id: "slot-parent-host-a",
      width: 10,
      height: 1,
    })
    const parentB = new BoxRenderable(setup.renderer, {
      id: "slot-parent-host-b",
      width: 10,
      height: 1,
    })

    setup.renderer.root.add(parentA)
    setup.renderer.root.add(parentB)

    const slot = createSlotNode()

    try {
      slot.parent = parentA
      const childA = slot.getSlotChild(parentA)
      if (!(childA instanceof LayoutSlotRenderable)) throw new Error("Expected layout placeholder")
      parentA.add(childA)

      slot.parent = parentB
      const childB = slot.getSlotChild(parentB)
      if (!(childB instanceof LayoutSlotRenderable)) throw new Error("Expected layout placeholder")
      parentB.add(childB)

      expect(slot.parent).toBe(parentB)

      if (cleanup === "remove") {
        parentB.remove(childB)
        slot.didRemoveSlotChild(parentB, childB)
      } else {
        parentB.destroyRecursively()
      }

      expect(slot.parent).toBe(parentA)
      expect(parentA.getChildren()[0]).toBe(childA)
      expect(parentB.getChildren()).toHaveLength(0)
      expect(childA.isFreed()).toBe(false)
      expect(childB.isFreed()).toBe(true)

      setup.renderer.destroy()
      expect(childA.isFreed()).toBe(true)
    } finally {
      setup.renderer.destroy()
      slot.destroy()
    }
  })
})

import { afterEach, describe, expect, it } from "bun:test"
import { ASCIIFontRenderable } from "../renderables/ASCIIFont.js"
import { createTestRenderer, type TestRenderer } from "../testing/test-renderer.js"
import { ASCIIFontSelectionHelper, type LocalSelectionBounds } from "./selection.js"

function helper() {
  return new ASCIIFontSelectionHelper(
    () => "HI",
    () => "tiny",
  )
}

function bounds(anchorX: number, focusX: number, anchorY = 0, focusY = 0): LocalSelectionBounds {
  return {
    anchorX,
    anchorY,
    focusX,
    focusY,
    isActive: true,
    behavior: "cell",
  }
}

describe("ASCIIFontSelectionHelper", () => {
  // tiny "H" is 3 cols, letterspace 1, "I" is 1 col. Positions: H@0, I@4.
  const hStart = 0
  const iStart = 4
  const height = 2
  const width = 5

  it.each([
    ["within H", hStart, 1, { start: 0, end: 1 }],
    ["at the right edge of H", hStart, 2, { start: 0, end: 1 }],
    ["from H to I", hStart, iStart, { start: 0, end: 2 }],
    ["from I to H", iStart, hStart, { start: 0, end: 2 }],
  ] as const)("selects occupied characters %s", (_name, anchorX, focusX, expected) => {
    const sel = helper()
    sel.onLocalSelectionChanged(bounds(anchorX, focusX), width, height)

    expect(sel.getSelection()).toEqual(expected)
  })

  it("stays empty on a press without drag", () => {
    const sel = helper()
    const changed = sel.onLocalSelectionChanged(bounds(hStart, hStart), width, height)

    expect(sel.getSelection()).toBe(null)
    expect(changed).toBe(false)
  })

  it("clears when the local selection is inactive", () => {
    const sel = helper()
    sel.onLocalSelectionChanged(bounds(hStart, iStart), width, height)
    expect(sel.hasSelection()).toBe(true)

    sel.onLocalSelectionChanged(null, width, height)
    expect(sel.hasSelection()).toBe(false)
  })

  it("uses vertical reading order outside the glyph row", () => {
    const sel = helper()
    sel.onLocalSelectionChanged(bounds(width, -1, -1, height), width, height)

    expect(sel.getSelection()).toEqual({ start: 0, end: 2 })
  })
})

describe("ASCIIFontRenderable selection", () => {
  let renderer: TestRenderer | undefined

  afterEach(() => renderer?.destroy())

  it("keeps unchanged active selections in renderer copy state", async () => {
    const test = await createTestRenderer({ width: 20, height: 4 })
    renderer = test.renderer
    const font = new ASCIIFontRenderable(renderer, { text: "HI", font: "tiny" })
    renderer.root.add(font)
    await test.renderOnce()

    renderer.startSelection(font, font.x, font.y)
    renderer.updateSelection(font, font.x + 4, font.y)
    renderer.updateSelection(font, font.x + 4, font.y, { finishDragging: true })

    expect(renderer.getSelection()?.getSelectedText()).toBe("HI")
  })
})

import { test, expect, beforeEach, afterEach, describe } from "bun:test"
import { Renderable, type RenderableOptions } from "../Renderable.js"
import { createTestRenderer, type TestRenderer } from "../testing/test-renderer.js"
import type { RenderContext } from "../types.js"

class TestRenderable extends Renderable {
  constructor(ctx: RenderContext, options: RenderableOptions) {
    super(ctx, options)
  }
}

let testRenderer: TestRenderer
let renderOnce: () => Promise<void>

beforeEach(async () => {
  ;({ renderer: testRenderer, renderOnce } = await createTestRenderer({}))
})

afterEach(() => {
  testRenderer.destroy()
})

describe("Renderable - Opacity", () => {
  test("defaults to 1.0", () => {
    const renderable = new TestRenderable(testRenderer, { id: "test-opacity" })
    expect(renderable.opacity).toBe(1.0)
  })

  test("accepts opacity in constructor options", () => {
    const renderable = new TestRenderable(testRenderer, {
      id: "test-opacity-options",
      opacity: 0.5,
    })
    expect(renderable.opacity).toBe(0.5)
  })

  test("clamps opacity to 0-1 range via setter", () => {
    const renderable = new TestRenderable(testRenderer, { id: "test-clamp" })

    renderable.opacity = 1.5
    expect(renderable.opacity).toBe(1.0)

    renderable.opacity = -0.5
    expect(renderable.opacity).toBe(0.0)

    renderable.opacity = 0.7
    expect(renderable.opacity).toBe(0.7)
  })

  test("clamps opacity from constructor options", () => {
    const r1 = new TestRenderable(testRenderer, {
      id: "test-clamp-high",
      opacity: 2.0,
    })
    expect(r1.opacity).toBe(1.0)

    const r2 = new TestRenderable(testRenderer, {
      id: "test-clamp-low",
      opacity: -1,
    })
    expect(r2.opacity).toBe(0.0)
  })

  test("handles opacity of 0 (fully transparent)", async () => {
    const renderable = new TestRenderable(testRenderer, {
      id: "invisible",
      width: 10,
      height: 5,
      opacity: 0,
    })
    testRenderer.root.add(renderable)

    expect(renderable.opacity).toBe(0)

    // Render should not crash with zero opacity
    await renderOnce()
  })

  test("nested renderables maintain independent opacity values", async () => {
    const parent = new TestRenderable(testRenderer, {
      id: "parent",
      width: 20,
      height: 10,
      opacity: 0.5,
    })

    const child = new TestRenderable(testRenderer, {
      id: "child",
      width: 10,
      height: 5,
      opacity: 0.8,
    })

    parent.add(child)
    testRenderer.root.add(parent)
    await renderOnce()

    expect(parent.opacity).toBe(0.5)
    expect(child.opacity).toBe(0.8)
  })

  test("opacity changes trigger render request", () => {
    const renderable = new TestRenderable(testRenderer, { id: "test-render" })
    testRenderer.root.add(renderable)

    const initialOpacity = renderable.opacity
    renderable.opacity = 0.3

    expect(renderable.opacity).not.toBe(initialOpacity)
    expect(renderable.opacity).toBe(0.3)
  })

  test("setting same opacity value does not update", () => {
    const renderable = new TestRenderable(testRenderer, {
      id: "test-same",
      opacity: 0.5,
    })

    // Set to same value - should not trigger change
    renderable.opacity = 0.5
    expect(renderable.opacity).toBe(0.5)
  })
})

import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs"
import { tmpdir } from "node:os"
import { join } from "node:path"
import { plugin as registerPlugin } from "bun"
import { createRuntimePlugin } from "../runtime-plugin.js"

const tempRoot = mkdtempSync(join(tmpdir(), "core-runtime-plugin-preserve-specifiers-fixture-"))
const hostModuleDir = join(tempRoot, "host")
const externalPluginDir = join(tempRoot, "external-plugin")
const foreignEffectDir = join(externalPluginDir, "node_modules", "effect")
const pluginDependencyDir = join(externalPluginDir, "node_modules", "plugin-local-dependency")
const hostModulePath = join(hostModuleDir, "host-runtime.ts")
const externalPluginEntryPath = join(externalPluginDir, "index.ts")

mkdirSync(hostModuleDir, { recursive: true })
mkdirSync(foreignEffectDir, { recursive: true })
mkdirSync(pluginDependencyDir, { recursive: true })

writeFileSync(
  join(foreignEffectDir, "package.json"),
  JSON.stringify({
    name: "effect",
    type: "module",
    exports: { ".": "./index.js", "./Option": "./Option.js" },
  }),
)
writeFileSync(join(foreignEffectDir, "index.js"), 'export const Effect = "foreign-effect"\n')
writeFileSync(join(foreignEffectDir, "Option.js"), 'export const some = "foreign-option"\n')

writeFileSync(
  join(pluginDependencyDir, "package.json"),
  JSON.stringify({ name: "plugin-local-dependency", type: "module", exports: "./index.js" }),
)
writeFileSync(join(pluginDependencyDir, "index.js"), 'export const marker = "resolved-from-plugin-node-modules"\n')

writeFileSync(
  hostModulePath,
  ['import { marker } from "plugin-local-dependency"', "export const hostRuntimeMarker = marker"].join("\n"),
)

writeFileSync(
  externalPluginEntryPath,
  [
    'import { marker as coreMarker } from "@opentui/core"',
    'import { hostRuntimeMarker } from "fixture-host-runtime"',
    'import { Effect } from "effect"',
    'import { some } from "effect/Option"',
    "console.log(`core=${coreMarker};effect=${Effect};option=${some};hostDep=${hostRuntimeMarker}`)",
    "export const noop = 1",
  ].join("\n"),
)

registerPlugin.clearAll()

registerPlugin({
  name: "fixture-host-build-modules",
  setup(build) {
    build.module("effect", () => ({ exports: { Effect: "host-effect" }, loader: "object" }))
    build.module("effect/Option", () => ({ exports: { some: "host-option" }, loader: "object" }))
  },
})

registerPlugin(
  createRuntimePlugin({
    core: { marker: "host-core" },
    additional: {
      "fixture-host-runtime": async () => (await import(hostModulePath)) as Record<string, unknown>,
    },
    // Runtime modules still take precedence when a predicate also matches them.
    preserve: (specifier) =>
      specifier === "@opentui/core" ||
      specifier === "fixture-host-runtime" ||
      specifier === "effect" ||
      specifier.startsWith("effect/"),
  }),
)

try {
  await import(externalPluginEntryPath)
} finally {
  registerPlugin.clearAll()
  rmSync(tempRoot, { recursive: true, force: true })
}

